// Auto-generated by the per-command split.
const os = require('os');
const dns = require('dns').promises;
const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

const SPORTS_CMDS = ['football', 'basketball', 'cricket', 'tennis', 'baseball', 'hockey'];

function buildCommand() {
  const __args = [SPORTS_CMDS, 'Sports', 'Get the latest result for a team', async ({ sock, from, msg, args, body, settings, cfg }) => {
  const team = args.join(' ');
  if (!team) return sock.sendMessage(from, { text: 'Usage: .football Arsenal' }, { quoted: msg });
  try {
    const searchRes = await fetch(`https://www.thesportsdb.com/api/v1/json/3/searchteams.php?t=${encodeURIComponent(team)}`);
    const searchData = await searchRes.json();
    const found = searchData.teams?.[0];
    if (!found) return sock.sendMessage(from, { text: 'Team not found.' }, { quoted: msg });
    const lastRes = await fetch(`https://www.thesportsdb.com/api/v1/json/3/eventslast.php?id=${found.idTeam}`);
    const lastData = await lastRes.json();
    const event = lastData.results?.[0];
    if (!event) return sock.sendMessage(from, { text: 'No recent results found.' }, { quoted: msg });
    await sock.sendMessage(from, {
      text: `🏆 *${found.strTeam}*\n${event.strEvent}\nScore: ${event.intHomeScore} - ${event.intAwayScore}\nDate: ${event.dateEvent}`
    }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Sports data unavailable right now.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
